INSERT OR REPLACE INTO episodes (id, show, number, title, description, show_notes, audio_url, duration, cover_image, guests, tags, spotify_url, apple_url, youtube_url, status, published_at, created_at, updated_at) VALUES ('clh-003', 'culture-lives-here', 3, 'Streetwear After the Hype', 'What happens to a scene when the lines disappear? A designer on building a brand people wear instead of flip.', '## In this episode

- Cold open and what we''ve been listening to this week
- The main conversation
