INSERT OR REPLACE INTO playlists (id, title, description, spotify_id, moods, highlights, cover_image, curator, sort, status, created_at, updated_at) VALUES ('pl-studio-focus', 'Studio Focus', 'Instrumentals for editing days and long sessions. No lyrics, no distractions.', '37i9dQZF1DWWQRwui0ExPn', '["Lo-fi","Focus","Instrumental"]', '["Sample Loop — Producer J","Sample Tape — Producer K","Sample Keys — Producer L"]', 'https://picsum.photos/seed/pl-focus/800/800', 'Culture Lives Here', 4, 'published', '2026-11-16T00:00:00.000Z', '2026-11-16T00:00:00.000Z');
